最小 Agent 实战——天气查询本实战案例使用Bun + TypeScript 创建项目及文件用 Bun + TypeScript，零依赖：1234567mkdir agent-loop &amp;&amp; cd agent-loopbun init -y // 初始化bun项目type nul &gt; prompt.md // 创建 prompt.md 文件type nul &gt; tools.ts // 创建 tools.ts 文件type nul &gt; API_KEY.md // 创建 API_KEY.md 文件ren index.ts main.ts // 修改入口文件名 完整的项目结构如下：123456agent-loop/├── main.ts # 核心 Agent Loop├── tools.ts # 工具定义├── prompt.md # 系统提示词├── API_KEY.md # LLM密钥└── package.json 工具定义(tools.ts)定义两个最小集的工具：获取当前时间和查询天气。12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364export type ToolName = &quot;getWeather&quot; | &quot;getTime&quot;export type ToolFn = (input: string) =&gt; Promise&lt;string&gt;type WeatherInput = &#123; error: string &#125; | &#123; city: string; time: string &#125;/** * 解析 getWeather 工具的输入参数，期望输入为 JSON 字符串，包含 city 和 time 字段 * @param input 原始输入字符串 * @returns 解析后的 WeatherInput 对象，包含 city 和 time，或 error 字段描述解析错误 */function parseWeatherInput(input: string): WeatherInput &#123; try &#123; const parsed = JSON.parse(input) const city = parsed?.city const time = parsed?.time if (!city || typeof city !== &quot;string&quot;) &#123; return &#123; error: &quot;getWeather 需要 city 字符串&quot; &#125; &#125; if (!time || typeof time !== &quot;string&quot;) &#123; return &#123; error: &quot;getWeather 需要 time 字符串&quot; &#125; &#125; return &#123; city: city.trim(), time: time.trim() &#125; &#125; catch &#123; return &#123; error: &apos;getWeather 参数需为 JSON，如 &#123;&quot;city&quot;:&quot;沈阳&quot;,&quot;time&quot;:&quot;2026-02-27 10:00&quot;&#125;&apos; &#125; &#125;&#125;/** * 根据城市和时间生成模拟天气信息 * @param city 城市名称 * @param time 时间字符串，格式不限，但建议包含日期和时间信息 * @returns 天气信息字符串 */function buildMockWeather(city: string, time: string): string &#123; const conditions = [&quot;晴&quot;, &quot;多云&quot;, &quot;阴&quot;, &quot;小雨&quot;, &quot;阵雨&quot;] const winds = [&quot;东北风 2 级&quot;, &quot;东风 3 级&quot;, &quot;西南风 2 级&quot;, &quot;北风 1 级&quot;] const seed = Array.from(`$&#123;city&#125;|$&#123;time&#125;`).reduce( (acc, ch) =&gt; acc + ch.charCodeAt(0), 0, ) const condition = conditions[seed % conditions.length] ?? &quot;晴&quot; const wind = winds[seed % winds.length] ?? &quot;微风 1 级&quot; const temp = 12 + (seed % 20) const humidity = 35 + (seed % 55) return `天气信息：$&#123;city&#125; 在 $&#123;time&#125; 的天气为$&#123;condition&#125;，气温 $&#123;temp&#125;°C，$&#123;wind&#125;，湿度 $&#123;humidity&#125;%。`&#125;/** * 工具函数集合，供 Agent 调用 */export const TOOLKIT: Record&lt;ToolName, ToolFn&gt; = &#123; async getTime() &#123; return new Date().toISOString() &#125;, async getWeather(rawInput: string) &#123; const parsed = parseWeatherInput(rawInput.trim()) if (&quot;error&quot; in parsed) return parsed.error return buildMockWeather(parsed.city, parsed.time) &#125;,&#125; 系统提示词（prompt.md）系统提示词告诉模型如何使用这两个工具，以及输出的格式要求。123456789101112131415161718192021你是天气查询的工具型助手，回答要简洁。可用工具（action 的 tool 属性需与下列名称一致）：- getTime: 返回当前 time 字符串，参数为空。- getWeather: 返回模拟天气信息字符串，参数为 JSON，如 &#123;&quot;city&quot;:&quot;沈阳&quot;,&quot;time&quot;:&quot;2026-02-27 10:00&quot;&#125;。回复格式（严格使用 XML，小写标签）：&lt;thought&gt;对问题的简短思考&lt;/thought&gt;&lt;action tool=&quot;工具名&quot;&gt;工具输入&lt;/action&gt; &lt;!-- 若需要工具 --&gt;等待 &lt;observation&gt; 后再继续思考。如果已可直接回答，则输出：&lt;final&gt;最终回答（中文，必要时引用数据来源）&lt;/final&gt;规则：- 每次仅调用一个工具；工具输入要尽量具体。- 当用户只问“现在几点”时，优先调用 getTime。- 查询天气时，必须调用 getWeather，并提供 city 和 time 两个字段。- 如果拿到 observation 后有了答案，应输出 &lt;final&gt; 而不是重复调用。- 未知工具时要说明，但仍用 XML 格式。- 避免幻觉，不确定时请说明。 LLM密钥(API_KEY.md)笔者使用的是QWen大模型1sk-8888888888888888888888888 核心Loop代码(main.ts)这是整个Agent的核心——40行代码实现ReAct循环 &#123; TOOLKIT, type ToolName &#125; from &quot;./tools&quot;type Role = &quot;system&quot; | &quot;user&quot; | &quot;assistant&quot;type ChatMessage = &#123; role: Role content: string&#125;type ParsedAssistant = &#123; action?: &#123; tool: string; input: string &#125; final?: string&#125;type QWenMessage = &#123; content?: string &#125;type QWenChoice = &#123; message?: QWenMessage &#125;type QWenResponse = &#123; choices?: QWenChoice[] &#125;let API_KEY:string = &apos;&apos;/** * 调用 QWen API 获取模型回复 * @param messages 对话消息列表，包含 system、user 和 assistant 角色的消息 * @returns 模型生成的回复文本 * @throws 如果 API 请求失败或返回格式不正确，将抛出错误 */async function callLLMs(messages: ChatMessage[]): Promise&lt;string&gt; &#123; const res = await fetch(&quot;https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions&quot;, &#123; method: &quot;POST&quot;, headers: &#123; &quot;Content-Type&quot;: &quot;application/json&quot;, Authorization: `Bearer $&#123;API_KEY&#125;`, &#125;, body: JSON.stringify(&#123; model: &quot;qwen3.5-plus&quot;, messages, temperature: 0.35, &#125;), &#125;) if (!res.ok) &#123; const text = await res.text() throw new Error(`QWen API 错误: $&#123;res.status&#125; $&#123;text&#125;`) &#125; const data = (await res.json()) as QWenResponse const content = data.choices?.[0]?.message?.content if (typeof content !== &quot;string&quot;) &#123; throw new Error(&quot;QWen 返回内容为空&quot;) &#125; return content&#125;/** * 解析 Assistant 回复，提取工具调用信息或最终回答 * @param content Assistant 回复的文本内容，可能包含 &lt;action&gt; 或 &lt;final&gt; 标签 * @returns ParsedAssistant 对象，包含 action（工具调用信息）或 final（最终回答）字段 */function parseAssistant(content: string): ParsedAssistant &#123; const actionMatch = content.match( /&lt;action[^&gt;]*tool=&quot;([^&quot;]+)&quot;[^&gt;]*&gt;([\s\S]*?)&lt;/action&gt;/i, ) const finalMatch = content.match(/&lt;final&gt;([\s\S]*?)&lt;/final&gt;/i) const parsed: ParsedAssistant = &#123;&#125; if (actionMatch) &#123; parsed.action = &#123; tool: actionMatch[1] as ToolName, input: actionMatch[2]?.trim() ?? &quot;&quot;, &#125; &#125; if (finalMatch) &#123; parsed.final = finalMatch[1]?.trim() &#125; return parsed&#125;/** * Agent 主循环，负责与 LLM 交互、解析回复、调用工具并更新对话历史 * @param question * @returns 最终回答字符串，或错误提示 */async function AgentLoop(question: string) &#123; API_KEY = await Bun.file(&quot;API_KEY.md&quot;).text() const systemPrompt = await Bun.file(&quot;prompt.md&quot;).text() const history: ChatMessage[] = [ &#123; role: &quot;system&quot;, content: systemPrompt &#125;, &#123; role: &quot;user&quot;, content: question &#125;, ] for (let step = 0; step &lt; 10; step++) &#123; const assistantText = await callLLMs(history) console.log(`
[LLM 第 $&#123;step + 1&#125; 轮输出]
$&#123;assistantText&#125;
`) history.push(&#123; role: &quot;assistant&quot;, content: assistantText &#125;) const parsed = parseAssistant(assistantText) if (parsed.final) &#123; return parsed.final &#125; if (parsed.action) &#123; const toolFn = TOOLKIT[parsed.action.tool as ToolName] let observation: string if (toolFn) &#123; observation = await toolFn(parsed.action.input) &#125; else &#123; observation = `未知工具: $&#123;parsed.action.tool&#125;` &#125; console.log(`&lt;observation&gt;$&#123;observation&#125;&lt;/observation&gt;
`) history.push(&#123; role: &quot;user&quot;, content: `&lt;observation&gt;$&#123;observation&#125;&lt;/observation&gt;`, &#125;) continue &#125; break // 未产生 action 或 final &#125; return &quot;未能生成最终回答，请重试或调整问题。&quot;&#125;/** * 程序入口，读取用户问题，调用 AgentLoop 获取回答并输出 */async function main() &#123; const userQuestion = process.argv.slice(2).join(&quot; &quot;) || &quot;沈阳现在天气如何？&quot; console.log(`用户问题: $&#123;userQuestion&#125;`) try &#123; const answer = await AgentLoop(userQuestion) console.log(&quot;
=== 最终回答 ===&quot;) console.log(answer) &#125; catch (err) &#123; console.error(`运行失败: $&#123;(err as Error).message&#125;`) &#125;&#125;await main() 运行123456789101112131415161718192021222324bun main.ts # 执行bun命令用户问题: 沈阳现在天气如何？[LLM 第 1 轮输出]&lt;thought&gt;用户询问沈阳当前天气，需要先获取当前时间，再调用天气查询工具&lt;/thought&gt;&lt;action tool=&quot;getTime&quot;&gt;&lt;/action&gt;&lt;observation&gt;2026-03-17T02:46:55.089Z&lt;/observation&gt;[LLM 第 2 轮输出]&lt;thought&gt;已获取当前时间，现在调用 getWeather 查询沈阳天气&lt;/thought&gt;&lt;action tool=&quot;getWeather&quot;&gt;&#123;&quot;city&quot;:&quot;沈阳&quot;,&quot;time&quot;:&quot;2026-03-17 02:46&quot;&#125;&lt;/action&gt;&lt;observation&gt;天气信息：沈阳 在 2026-03-17 02:46 的天气为小雨，气温 20°C，东北风 2 级，湿度 83%。&lt;/observation&gt;[LLM 第 3 轮输出]&lt;final&gt;沈阳现在（2026-03-17 02:46）的天气为小雨，气温 20°C，东北风 2 级，湿度 83%。&lt;/final&gt;=== 最终回答 ===沈阳现在（2026-03-17 02:46）的天气为小雨，气温 20°C，东北风 2 级，湿度 83%。 源码源码地址 参考从零构建一个 Mini Claude Code：面向初学者的 Agent 开发实战指南

小巧的html模板引擎 小巧的html模板引擎今天看coco大神的github，看到了他写的html模板引擎，默默地记录下来，其实，模板引擎我自己也写过一个，不过总觉得大神写的一定比我的好，点击这是我写的先贴出代码12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758/** * coTemplate * */(function(name, definition) &#123; if (typeof define === 'function') &#123; define(definition); &#125; else &#123; this[name] = definition(); &#125;&#125;)('cotemplate', function() &#123; var tplReg = /\$\&#123;\s*([^\&#123;\&#125;\s]+)\s*\&#125;/g; var jsReg = /(^( )?(if|for|else|switch|case|break|&#123;|&#125;))(.*)?/g; var code = 'var r=[];
'; var match = 'undefined'; var pointer = 0; /** * 添加单行逻辑 * @param &#123;*&#125; line */ function lineAdd(line) &#123; code += 'r.push("' + line.replace(/"/g, '\"') + '");
'; &#125; /** * 模板拼接 * @param &#123;String&#125; tpl 模板字符串 * @param &#123;Objcet&#125; data 模板内替换对象 */ function cotemplate(tpl, data) &#123; while (match = tplReg.exec(tpl)) &#123; // 添加非逻辑部分 lineAdd(tpl.slice(pointer, match.index)); // 添加逻辑部分 "$&#123;" + match[1] + "&#125;"; code += ('r.push(String(this.' + match[1] + '));'); pointer = match.index + match[0].length; &#125; // 添加代码的最后一截 lineAdd(tpl.substr(pointer, tpl.length - pointer)); // 返回结果，在这里我们就拿到了装入数组后的代码 code += 'return r.join("");'; console.log(code); return new Function(code.replace(/[	
]/g, '')).apply(data); &#125; /** * export */ return cotemplate;&#125;); 用法Demo1234567891011121314151617181920212223242526&lt;script src="../js/cotemplate.js"&gt;&lt;/script&gt;&lt;script&gt;var data = &#123; name: 'Coco', info: &#123; age: 18 &#125;, bar: &#123; foo: &#123; else: 'co-template' &#125; &#125;&#125;var tpl = ` &lt;p&gt;name:$&#123;coco&#125;&lt;/p&gt; &lt;p&gt;Age:$&#123;info.age&#125;&lt;/p&gt; &lt;div&gt;$&#123;bar.foo.else&#125;&lt;/div&gt; `;cotemplate(tpl, data);// &lt;p&gt;Name:Coco&lt;/p&gt; // &lt;p&gt;Age:18&lt;/p&gt; // &lt;div&gt;HTML-template:co-template&lt;/div&gt; &lt;/script&gt;
